import CONSTANTS from "redux/constants";

export const socketReducer = (
  state = {
    connected: false,
    connecting: true, 
    socket: null,
    curChatUser: {
      username: "",
      id: "",
      email: "",
    },
    histories: [],
    rosters: [],
  },
  action
) => {
  switch (action.type) {
    case CONSTANTS.SOCKET_CONNECT:
      return {
        ...state,
        socket: action.payload.socket,
        connected: true,
        connecting: false,
      };
    case CONSTANTS.SOCKET_STATUS:
      return {
        ...state,
        connected: action.payload.connected,
        connecting: action.payload.connecting,
      };
    case CONSTANTS.SOCKET_DISCONNECT:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SOCKET_RECONNECT:
      return {
        ...state,
        socket: action.payload,
        connected: true,
        connecting: false,
      };
    case CONSTANTS.SOCKET_RECONNECTING:
      return { ...state, socket: null, connected: false, connecting: true };
    case CONSTANTS.SOCKET_RECONNECT_ERROR:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SOCKET_RECONNECT_FAILED:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SOCKET_ERROR:
      return { ...state, socket: null, connected: false, connecting: false };
    case CONSTANTS.SET_CHAT_USER:
      return {
        ...state,

          curChatUser: {
            ...state.curChatUser,
            username: action.payload.username,
            id: action.payload.id,
            email: action.payload.email,
          },
      
      };
    case CONSTANTS.RETRIEVE_HISTORY:
      return {...state, histories: action.payload};
    case CONSTANTS.RECEIVE_MESSAGE:
      return {...state, histories: [...state.histories, action.payload]};
    case CONSTANTS.SEND_MESSAGE:
      return {...state, histories: [...state.histories, action.payload]};
    case CONSTANTS.GET_ROSTER:
      return {...state, rosters: action.payload.rosters};
    case CONSTANTS.ADD_ROSTER:
      return {...state, histories: [...state.rosters, action.payload]};
    default:
      return state;
  }
};
