import React, { useState, useEffect, useRef } from "react";
import { useLocation, Switch, Redirect, Route } from "react-router-dom";
import AdminNavbar from "components/Navbars/AdminNavbar";
import Footer from "components/Footer/Footer";
import Sidebar from "components/Sidebar/Sidebar";
import { Modal, Card, Form, Row, Col } from "react-bootstrap";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPhone, faTimes } from "@fortawesome/fontawesome-free-solid";
import routes from "routes.js";
import sidebarImage from "assets/img/sidebar-3.jpg";
import AddUser from "views/AddUser";
import EditUser from "views/EditUser";
import NotFound from "views/NotFound";
import AddAgeGroup from "views/Data/AgeGroup/AddAgeGroup";
// chat required imports
import { connect } from "react-redux";

import EditAgeGroup from "views/Data/AgeGroup/EditAgeGroup";
import AddCallType from "views/Data/CallType/AddCallType";
import EditCallType from "views/Data/CallType/EditCallType";
import AddShift from "views/Data/Shift/AddShift";
import EditShift from "views/Data/Shift/EditShift";
import AddRole from "views/Data/Roles/AddRole";
import EditRole from "views/Data/Roles/EditRole";

import CustomizedButton from "components/common/CustomizedButton";
import { isSelected } from "helpers/array.helper";
import { socketConnect } from "redux/action/socket";

// chat required imports
let defaultForm = {
  facilitator: "",
  customerUserName: "",
  callFrom: "",
  firstname: "",
  middlename: "",
  lastname: "",
  address: "",
  province: "",
  email: "",
  phone: "",
  gender: "",
  ageGroup: "",
  shift: "",
  callType: [],
};

function AdminLayout(props) {
  const [image, setImage] = React.useState(sidebarImage);
  const [color, setColor] = React.useState("white");
  const [hasImage, setHasImage] = React.useState(true);
  const [loading, setLoading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const location = useLocation();
  const mainPanel = React.useRef(null);

  //Chat Required Stuff
  const [timer, setTimer] = useState("");
  const [start, setStart] = useState(null);
  const [formData, setFormData] = useState(defaultForm);
  const [data, setData] = useState({});

  // chat Required Stuff
  const getBrandText = () => {
    for (let i = 0; i < routes.length; i++) {
      if (location.pathname.indexOf(routes[i].layout + routes[i].path) > -1) {
        return routes[i].name;
      }
    }

    return location.pathname.split("/").pop();
  };

  React.useEffect(() => {
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    mainPanel.current.scrollTop = 0;
    if (
      window.innerWidth < 993 &&
      document.documentElement.className.indexOf("nav-open") !== -1
    ) {
      document.documentElement.classList.toggle("nav-open");
      var element = document.getElementById("bodyClick");
      element.parentNode.removeChild(element);
    }
  }, [location]);

  const loggedInUser = localStorage.getItem("loggedInUser");
  // Chat and Call codes

  // useEffect(() => {
  //   const getTimeRemaining = () => {
  //     const total = Date.now() - start;
  //     const s = Math.floor(total / 1000);
  //     const seconds = Math.floor(s % 60);
  //     const minutes = Math.floor((s / 60) % 60);
  //     const hours = Math.floor((s / 3600) % 24);
  //     setTimer(`${twoDigit(hours)}:${twoDigit(minutes)}:${twoDigit(seconds)}`);
  //   };
  //   if (start) {
  //     let reference = setInterval(getTimeRemaining, 1000);
  //     setReference(reference);
  //   } else {
  //     reference && clearInterval(reference);
  //   }
  // }, []);

  useEffect(() => {
    if(!props.io.connected){
      props.socketConnect();
    }
  }, [props.io.connected]);  
  const handleChange = (e) => {
    const { value, name } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const getRoutes = (routes) => {
    return routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        return (
          <Route
            path={prop.layout + prop.path}
            render={(props) => {
              return <prop.component {...props} />;
            }}
            key={key}
            exact
          />
        );
      }
    });
  };
  return (
    <>
      <div className="wrapper">
        <Sidebar color={color} image={hasImage ? image : ""} routes={routes} />
        <div className="main-panel" ref={mainPanel}>
          {/* <Button
            className="btn-fill btn-wd"
            variant="info"
            onClick={() => setShowModal(true)}
          >
            Launch Modal
          </Button> */}
          <AdminNavbar />
          <div className="content" id={getBrandText()}>
            {loggedInUser ? (
              <>
                <Switch>
                  {getRoutes(routes)}
                  <Route
                    exact
                    path={"/admin/user/add"}
                    component={AddUser}
                  ></Route>{" "}
                  <Route
                    exact
                    path={"/admin/user/edit/:id"}
                    component={EditUser}
                  ></Route>
                  {/* cage group */}
                  <Route
                    exact
                    path={"/admin/agegroup/add"}
                    component={AddAgeGroup}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/agegroup/edit/:id"}
                    component={EditAgeGroup}
                  ></Route>
                  {/* Call type Route */}
                  <Route
                    exact
                    path={"/admin/calltype/add"}
                    component={AddCallType}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/calltype/edit/:id"}
                    component={EditCallType}
                  ></Route>
                  {/* Shift Route */}
                  <Route
                    exact
                    path={"/admin/shift/add"}
                    component={AddShift}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/shift/edit/:id"}
                    component={EditShift}
                  ></Route>
                  {/* Role Route */}
                  <Route
                    exact
                    path={"/admin/role/add"}
                    component={AddRole}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/role/edit/:id"}
                    component={EditRole}
                  ></Route>
                  {/* <Route


                    exact
                    path={"/admin/call/voice-call"}
                    component={VoiceCall}
                  ></Route> */}
                  <Route component={NotFound}></Route>
                </Switch>
              </>
            ) : (
              <>
                <Switch>
                  <Redirect to="/auth/login" />
                </Switch>
              </>
            )}
          </div>
          <Footer />
        </div>
      </div>

      {/* Mini Modal */}
      <Modal
        className="modal-mini modal-primary"
        // show={showModal}
        // onHide={() => setShowModal(false)}
        backdrop="static"
      >
        <Modal.Body className="d-flex p-0">
          <div className="voice-call-page">
            <div className="call-header">
              <p className="font-weight-bold"> Checking </p>
            </div>
            <div className="d-flex align-items-center py-1 flex-column call-body">
              <div className="position-relative">
                <div className="avatar-box bg-light-danger">
                  <span className="avatar-label">Name</span>
                </div>
              </div>
              <div className="flex-grow-1">
                <span className="chat-username-sm">Name</span>
                <div className="text-muted small text-center">
                  <strong> {timer} </strong>
                </div>
              </div>
            </div>

            <div className="call-control-btns d-flex justify-content-center align-items-center w-100">
              <button
                type="button"
                // onClick={() => props.accept()}
                className="mr-3 ml-3 btn-circle btn-start-call d-md-inline-block btn"
              >
                {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
                <FontAwesomeIcon icon={faPhone} />
              </button>

              <button
                type="button"
                // onClick={() => props.declineCall(jid)}
                className="mr-3 ml-3 btn-circle btn-end-call d-md-inline-block btn"
              >
                {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
                <FontAwesomeIcon icon={faTimes} />
              </button>
            </div>
          </div>
          <Row>
            <Col md="12">
              <Card>
                <Card.Header>
                  <Card.Title as="h4"> Service Seeker Information </Card.Title>
                </Card.Header>

                <Card.Body>
                  {loading ? (
                    "loading..."
                  ) : (
                    <Form>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label>First Name</label>
                            <Form.Control
                              placeholder="First Name"
                              type="text"
                              name="firstname"
                              value={formData?.firstname}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label>Middle Name</label>
                            <Form.Control
                              placeholder="Middle Name"
                              type="text"
                              name="middlename"
                              value={formData?.middlename}
                              onChange={handleChange}
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label>Last Name</label>
                            <Form.Control
                              placeholder="Last Name"
                              type="text"
                              name="lastname"
                              value={formData?.lastname}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label> Address </label>
                            <Form.Control
                              placeholder="Address"
                              onChange={handleChange}
                              value={formData.address}
                              type="text"
                              name="address"
                            ></Form.Control>
                          </Form.Group>
                        </Col>

                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Province</label>
                            <select
                              required
                              onChange={handleChange}
                              name="province"
                              className="form-control"
                            >
                              <option>Province 1 </option>
                              <option>Province 2 </option>
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row>
                        <Col className="pr-1" md="5">
                          <Form.Group>
                            <label htmlFor="exampleInputEmail1">
                              Email address
                            </label>
                            <Form.Control
                              placeholder="Email"
                              type="email"
                              name="email"
                              value={formData.email}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label htmlFor="exampleInputPhone">Phone</label>
                            <Form.Control
                              placeholder="Phone"
                              onChange={handleChange}
                              value={formData.phone}
                              type="text"
                              name="phone"
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Gender</label>
                            <select
                              required
                              name="gender"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              <option
                                selected={isSelected("Male", formData.gender)}
                                value="Male"
                              >
                                Male{" "}
                              </option>
                              <option
                                selected={isSelected("Female", formData.gender)}
                                value="Female"
                              >
                                Female{" "}
                              </option>
                              <option
                                selected={isSelected("Other", formData.gender)}
                                value="Other"
                              >
                                Other{" "}
                              </option>
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Age Group</label>
                            <select
                              required
                              name="ageGroup"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.ageGroups?.map((ageGroup) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      ageGroup._id,
                                      formData.ageGroup
                                    )}
                                    key={ageGroup._id}
                                    value={ageGroup._id}
                                  >
                                    {ageGroup?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Shift</label>
                            <select
                              required
                              name="shift"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.shifts?.map((shift) => {
                                return (
                                  <option key={shift._id} value={shift._id}>
                                    {shift?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Call Type</label>
                            <select
                              required
                              name="callType"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.callTypes?.map((callType) => {
                                return (
                                  <option
                                    key={callType._id}
                                    value={callType._id}
                                  >
                                    {callType?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row className="mt-3">
                        <Col className="pr-1" md="12">
                          <CustomizedButton
                            isDisabled={
                              isSubmitting ||
                              [
                                "connected",
                                "calling",
                                "checking",
                                "failed",
                              ].includes(props?.call?.callStatus)
                            }
                            enabledLable="Submit"
                            disabledLable={
                              isSubmitting ? "Submitting..." : "Submit"
                            }
                          />
                        </Col>
                      </Row>

                      <div className="clearfix"></div>
                    </Form>
                  )}
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Modal.Body>
      </Modal>

      <video autoPlay={true} id="remote-video"></video>
      <video muted id="local-video"></video>
      {/* End Modal */}
    </>
  );
}

const mapStateToProps = (state) => ({
  io: state.io,
});

const mapDispatchToProps = (dispatch) => ({
  socketConnect: () => dispatch(socketConnect()),
});
export default connect(mapStateToProps, mapDispatchToProps)(AdminLayout);
